--[[
	Trijicon ACOG 4x
	A fixed four-power scope. Zooms in further than a red dot, and takes a
	moment longer to bring up.
]]

return {
	Name = "Trijicon ACOG 4x",
	Slot = "Optic",
	Config = {
		Handling = { AimFOV = 24, AimTime = 0.26 },
		Sway = { AimScale = 0.45 },
	},
}

--[[
	SureFire Scout
	A weapon light. The Light key switches it on and off; everyone sees the beam.
]]

return {
	Name = "SureFire Scout Light",
	Slot = "Side",
	Light = {
		Brightness = 5,
		Range = 55,
		Angle = 45,
	},
}

--[[
	EOTech XPS
	A holographic sight: a wide window and a ring reticle, no magnification.
]]

return {
	Name = "EOTech XPS",
	Slot = "Optic",
	Config = {
		Handling = { AimFOV = 50 },
	},
}

--[[
	AN/PEQ-15
	A laser sight. The Light key switches the beam on and off; everyone sees
	it. A steadier hand from the hip.
]]

return {
	Name = "AN/PEQ-15 Laser",
	Slot = "Side",
	Laser = {
		Color = Color3.fromRGB(255, 40, 40),
	},
	Tuning = { Spread = 0.85 },
}

--[[
	Aimpoint CompM4
	A red dot sight. Quicker to pick up than iron sights, no magnification.
]]

return {
	Name = "Aimpoint CompM4",
	Slot = "Optic",
	Config = {
		Handling = { AimFOV = 48 },
	},
}

--[[
	Nightforce ATACR
	A high-power scope. Once it is up to the eye the screen shows the view
	through it (Scope), and the weapon itself is hidden.
]]

return {
	Name = "Nightforce ATACR",
	Slot = "Optic",
	Scope = {
		Reticle = Color3.fromRGB(10, 10, 10),
	},
	Config = {
		Handling = { AimFOV = 12, AimTime = 0.32, AimWalkSpeedScale = 0.5 },
	},
}

--[[
	AAC M4-2000
	A suppressor. Quieter and higher pitched, no muzzle flash, a little less
	kick. The sound only carries a short way.
]]

return {
	Name = "AAC M4-2000 Suppressor",
	Slot = "Muzzle",
	Config = {
		Effects = {
			MuzzleFlash = { Enabled = false },
			Sounds = { FireVolume = 0.3, FirePitch = 1.4, RollOffMax = 160 },
		},
	},
	Tuning = { Recoil = 0.92 },
}

--[[
	Daniel Defense Vertical Grip
	A foregrip. The support hand holds it, and it steadies the weapon.
]]

return {
	Name = "Vertical Grip",
	Slot = "Underbarrel",
	Tuning = { Recoil = 0.85, Spread = 0.95 },
}

--!strict
--[[
	Schema
	Checks a user-written config table against Defaults and returns a clean
	copy. It never throws: anything wrong is reported and left out, so the
	default applies instead.

	The type of each field comes from its value in Defaults. This file only
	adds what a value alone cannot say: ranges, fixed choices and a one-line
	description. The plugin's config editor and the docs read the same rules.
]]

local Defaults = require(script.Parent.Defaults)

export type Rule = {
	doc: string,
	min: number?,
	max: number?,
	integer: boolean?,
	choices: { string }?,
	-- "keys": list of Enum.KeyCode / Enum.UserInputType names
	-- "choices": list where every item must be one of `choices`
	-- "strings": list of free strings
	-- "model": a child name or an Instance
	-- "free": anything; copied through unchecked
	-- "frame": exactly six numbers (position x, y, z; rotation x, y, z in degrees)
	kind: ("keys" | "choices" | "strings" | "model" | "free" | "frame")?,
}

export type Problem = {
	path: string,
	message: string,
}

